-- ============================================================
-- CMX 业务库手工种子：报表清单（cr_report_list 300 条及关联字典）
-- 前置条件：cr_* 表 DDL 由模型中心运行时部署，建表完成后方可执行
-- 幂等：DELETE 精确清理后 INSERT（原样保留）
-- 来源：docs/sql/seed/fico_cr_report_seed.sql
-- ============================================================

DELETE FROM cr_report_category WHERE code IN ('supervisory','internal','tax','consolidation','statutory');

-- 编报期间类型（日/周/月/季/半年/年）
DELETE FROM cr_period_type WHERE code IN ('day','week','month','quarter','halfyear','year');

-- 编制口径
DELETE FROM cr_entity_scope WHERE code IN ('single','consol','combined');

-- 金额单位
DELETE FROM cr_amount_unit WHERE code IN ('yuan','kyuan','wyuan');

-- 报表主档 cr_report_list：每「类别 × 期间」10 张 = 300 张
DELETE FROM cr_report_list WHERE code ~ '^(SUP|INT|TAX|CON|STA)_(DAY|WK|MON|QTR|HY|YR)_[0-9]{2}$';
